import{_ as t,o as i,c as a,ag as s}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"GUI System","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/gui.md","filePath":"en/modules/corelib/gui.md","lastUpdated":null}'),d={name:"en/modules/corelib/gui.md"};function o(n,e,r,l,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="gui-system" tabindex="-1">GUI System <a class="header-anchor" href="#gui-system" aria-label="Permalink to &quot;GUI System&quot;">​</a></h1><p>CoreLib provides GUI templates, open requests, session management, slot control, and click handling. Business modules reuse this infrastructure instead of implementing inventory events from scratch.</p><h2 id="used-by" tabindex="-1">Used by <a class="header-anchor" href="#used-by" aria-label="Permalink to &quot;Used by&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Usage</th></tr></thead><tbody><tr><td>EmakiForge</td><td>Forge GUI, recipe book.</td></tr><tr><td>EmakiStrengthen</td><td>Strengthening GUI, material slots, protection slots.</td></tr><tr><td>EmakiGem</td><td>Inlay, extraction, socket opening, and upgrade GUI.</td></tr><tr><td>EmakiSkills</td><td>Skill panel and trigger-selection GUI.</td></tr><tr><td>EmakiCooking</td><td>Steamer, oven, juicer, and fermentation-barrel GUI.</td></tr><tr><td>EmakiAttribute</td><td>Attribute point allocation GUI.</td></tr><tr><td>EmakiItem</td><td>Item repair GUI.</td></tr><tr><td>EmakiLevel</td><td>Level panel and leaderboard GUI.</td></tr><tr><td>EmakiStorage</td><td>Paged warehouse GUI.</td></tr></tbody></table><h2 id="menu-rendering-backend" tabindex="-1">Menu rendering backend <a class="header-anchor" href="#menu-rendering-backend" aria-label="Permalink to &quot;Menu rendering backend&quot;">​</a></h2><p><code>gui.backend</code> in <code>plugins/EmakiCoreLib/config.yml</code> decides how every Emaki menu is presented:</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>bukkit</code></td><td>Default. Opens a real server-side container and needs no extra plugin.</td></tr><tr><td><code>packet</code></td><td>CoreLib&#39;s built-in packet-based virtual menu. It reuses the same window when the row count changes, so the cursor is not reset. Requires PacketEvents; falls back to <code>bukkit</code> when it is missing.</td></tr><tr><td><code>auto</code></td><td>Uses <code>packet</code> when PacketEvents is installed, otherwise <code>bukkit</code>.</td></tr></tbody></table><p>The default stays <code>bukkit</code>, so upgrading CoreLib does not change existing menu behaviour.</p><h2 id="template-fields" tabindex="-1">Template fields <a class="header-anchor" href="#template-fields" aria-label="Permalink to &quot;Template fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Yes</td><td>Template id used by the module.</td></tr><tr><td><code>title</code></td><td>string/object</td><td>Yes</td><td>Inventory title. MiniMessage strings and TextConfig objects are supported.</td></tr><tr><td><code>rows</code></td><td>integer</td><td>Yes</td><td>Inventory rows, usually <code>1</code> to <code>6</code>.</td></tr><tr><td><code>slots</code></td><td>map</td><td>Yes</td><td>Slot definitions keyed by slot name.</td></tr></tbody></table><h2 id="slot-fields" tabindex="-1">Slot fields <a class="header-anchor" href="#slot-fields" aria-label="Permalink to &quot;Slot fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>key</code></td><td>string</td><td>Slot key used by business code.</td></tr><tr><td><code>slots</code></td><td><code>list&lt;number&gt;</code></td><td>Inventory indexes covered by this slot definition.</td></tr><tr><td><code>type</code></td><td>string</td><td>Business type label, such as <code>input</code>, <code>output</code>, <code>button</code>, or <code>decoration</code>.</td></tr><tr><td><code>item</code></td><td>object</td><td>Shared item definition containing <code>source</code>, <code>amount</code>, and <code>components</code>. Without <code>source</code>, it can act as a pure patch for a runtime item.</td></tr><tr><td><code>sounds</code></td><td>map</td><td>Click sounds keyed by click type.</td></tr></tbody></table><h2 id="unified-item-structure" tabindex="-1">Unified item structure <a class="header-anchor" href="#unified-item-structure" aria-label="Permalink to &quot;Unified item structure&quot;">​</a></h2><p>New configs and bundled defaults only write the nested canonical structure:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">minecraft-anvil</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    custom_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;green&gt;Confirm&lt;/green&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Click to execute&lt;/gray&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    item_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki:confirm</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enchantment_glint_override</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    $unset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">repairable</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    $reset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">attribute_modifiers</span></span></code></pre></div><ul><li><code>source</code> accepts every ItemSource shorthand registered in CoreLib; availability depends on the corresponding resolver/plugin.</li><li>A normal component value means <code>SET</code>; <code>$unset</code> removes a component and <code>$reset</code> restores the material prototype default.</li><li>Component IDs must be valid namespaced keys. IDs without a namespace default to <code>minecraft:</code>, while explicit namespaces are preserved; the same rule applies to <code>$unset</code> / <code>$reset</code> entries. Unknown IDs and invalid values for supported components are configuration errors.</li><li>Known components introduced after the current server version are skipped with a warning without linking newer typed classes.</li><li>Third-party sources are cloned first so source identity, PDC, and unknown components survive; only patches that Paper can safely transfer are applied.</li><li>Legacy <code>item: &lt;source&gt;</code> plus top-level <code>components</code>, <code>display_name</code>, and <code>lore</code> are still readable compatibility inputs. When both forms exist, nested <code>item</code> wins.</li><li>Real player-provided targets, materials, and business outputs remain controlled by session state and are not overwritten by template display items.</li></ul><h3 id="automatic-migration-of-legacy-gui-item-fields" tabindex="-1">Automatic migration of legacy GUI item fields <a class="header-anchor" href="#automatic-migration-of-legacy-gui-item-fields" aria-label="Permalink to &quot;Automatic migration of legacy GUI item fields&quot;">​</a></h3><p>Starting with CoreLib <code>4.5.11</code>, shared <code>gui/*.{yml,yaml}</code> files undergo a pure structural migration before normal <code>YamlDocument</code> loading and <code>GuiTemplateParser</code> parsing. The migration walks candidate configured-item nodes throughout the document, including regular <code>slots</code> and module-specific containers such as <code>pages/buttons</code> and <code>virtual_items</code>.</p><p>The mapping follows the runtime <code>LegacyConfiguredItemConverter</code> contract:</p><ul><li>Legacy <code>material</code>, <code>item_source</code> / <code>item_sources</code>, and scalar <code>item</code> sources move to <code>item.source</code>; <code>amount</code> moves to <code>item.amount</code>.</li><li>Legacy <code>display_name</code>, <code>item_name</code>, <code>lore</code>, <code>custom_model_data</code>, <code>enchantments</code>, <code>item_flags</code>, <code>hidden_components</code>, <code>unbreakable</code>, and related display fields move to <code>item.components</code>.</li><li>Existing canonical <code>item.source</code>, <code>item.amount</code>, and component values win. Legacy values never overwrite modern values in mixed files.</li><li>A candidate containing <code>components.raw</code> or <code>item.components.raw</code> is skipped as a whole so opaque raw component payloads are not rewritten.</li><li>Slot layout, sounds, actions, pagination rules, and other non-target business fields remain unchanged. Running the migration again produces no further changes.</li></ul><p>Before a changed batch is committed, every original file is backed up under the relevant plugin data directory at <code>migration-backups/configured-item-format/&lt;timestamp&gt;/</code>, preserving its path relative to the <code>gui/</code> source directory. The migrated YAML is written to a sibling temporary file and parsed again before replacement. If writing, validation, or replacement fails, the original remains intact or is restored from the batch backup, and GUI loading does not continue with an unverified migrated result. BoostedYAML preserves comments on untouched business nodes where its comment model allows, but a full configuration backup is still recommended before production upgrades.</p><p>This compatibility layer does not read version values from <code>config.yml</code>, language files, or plugin descriptors, and it is not version-gated. It runs solely when legacy fields are present. The implementation is contained in CoreLib&#39;s <code>item.migration.configureditem</code> package, with <code>GuiTemplateLoader</code> as the only GUI production bridge, so it can be removed as a unit after the compatibility window without leaving legacy rules in <code>YamlFiles</code>, <code>YamlDirectoryLoader</code>, or canonical parsers.</p><h2 id="editing-advice" tabindex="-1">Editing advice <a class="header-anchor" href="#editing-advice" aria-label="Permalink to &quot;Editing advice&quot;">​</a></h2><ol><li>Change display text first.</li><li>Then move decorative slots.</li><li>Adjust functional slots only after confirming the layout.</li><li>Test shift-click, drag, double-click, close handling, and full-inventory cases after each GUI change.</li></ol>`,24)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
